var rec = new GlideRecord('sys_dictionary');
rec.addQuery('name', 'v_st_fsm_schedule_event');
rec.addQuery('element', 'repeat_until');
rec.query();
while (rec.next()) {
    if(rec.getValue('internal_type') == "glide_date_time"){
        rec.setValue('internal_type', 'glide_date');
        rec.update();
    }
}
